package sourceobs

import (
	"regexp"
	"strings"
)

var transcriptMachineMarkers = []string{
	"<command-name>", "<command-message>", "<command-args>",
	"<local-command", "</local-command",
	"<task-notification>", "<task-id>",
	"[request interrupted",
	"messages below were generated by the user while running local commands",
	"resume the paused workflow by calling",
	"caveat: the messages below",
	// Tool/skill injections that arrive with role=user but are machinery, not the
	// operator speaking (found leaking through in the live 2026-07-11 dry-run).
	"base directory for this skill",
	"contents of the skill file",
	"here is useful information about the environment",
	"the following mcp servers",
}

var transcriptReminderPattern = regexp.MustCompile(`(?s)<system-reminder>.*?</system-reminder>`)
var transcriptCommandPattern = regexp.MustCompile(`(?s)<local-command-.*?>`)

func CleanTranscriptUserText(s string) string {
	s = transcriptReminderPattern.ReplaceAllString(s, "")
	s = transcriptCommandPattern.ReplaceAllString(s, "")
	return strings.TrimSpace(strings.Join(strings.Fields(s), " "))
}

// IsTranscriptMachineText identifies obvious harness injections, not a human assertion.
func IsTranscriptMachineText(text string) bool {
	lower := strings.ToLower(text)
	for _, marker := range transcriptMachineMarkers {
		if strings.Contains(lower, marker) {
			return true
		}
	}
	return strings.Contains(lower, "<environment_context>") || strings.HasPrefix(lower, "# agents.md instructions")
}
